#include <algorithm>
#include <cctype>
#include <cmath>
#include <set>
#include <sstream>
#include <string>
#include <vector>

struct Entity { int id; std::string name; std::string team; int hp; };
struct SortSpec { int column; bool ascending; };

class EntityBrowser
{
public:
    explicit EntityBrowser(std::vector<Entity> entities) : m_all{ std::move(entities) } {}

    void setFilter(const std::string& filter) { m_filter = filter; }
    void setSort(const std::vector<SortSpec>& specs) { m_specs = specs; }

    std::vector<int> rows() const
    {
        std::vector<const Entity*> shown;
        for (const Entity& e : m_all) if (matches(e.name + " " + e.team, m_filter)) shown.push_back(&e);
        if (!m_specs.empty())
            std::stable_sort(shown.begin(), shown.end(), [&](const Entity* a, const Entity* b) {
                for (const SortSpec& s : m_specs)
                {
                    const int c{ compare(*a, *b, s.column) };
                    if (c != 0) return s.ascending ? c < 0 : c > 0;
                }
                return false;
            });
        std::vector<int> ids;
        for (const Entity* e : shown) ids.push_back(e->id);
        return ids;
    }

    void click(int id, bool ctrl, bool shift)
    {
        const std::vector<int> order{ rows() };
        const auto a{ std::find(order.begin(), order.end(), m_anchor) };
        const auto b{ std::find(order.begin(), order.end(), id) };
        if (shift && m_anchor != -1 && a != order.end() && b != order.end())
        {
            if (!ctrl) m_selected.clear();
            auto from{ a }, to{ b };
            if (from > to) std::swap(from, to);
            for (auto it{ from }; it <= to; ++it) m_selected.insert(*it);
            return;
        }
        if (ctrl) { if (!m_selected.erase(id)) m_selected.insert(id); }
        else { m_selected.clear(); m_selected.insert(id); }
        m_anchor = id;
    }

    std::vector<int> selected() const { return { m_selected.begin(), m_selected.end() }; }

    std::vector<int> visibleRows(float scrollY, float viewHeight, float rowHeight) const
    {
        const std::vector<int> order{ rows() };
        const int n{ static_cast<int>(order.size()) };
        if (n == 0 || rowHeight <= 0.0f) return {};
        int start{ static_cast<int>(std::floor(scrollY / rowHeight)) };
        int end{ static_cast<int>(std::ceil((scrollY + viewHeight) / rowHeight)) };
        start = std::clamp(start, 0, n);
        end = std::clamp(end, start, n);
        return { order.begin() + start, order.begin() + end };
    }

    void removeSelected()
    {
        m_all.erase(std::remove_if(m_all.begin(), m_all.end(), [&](const Entity& e) { return m_selected.count(e.id) > 0; }), m_all.end());
        m_selected.clear();
        m_anchor = -1;
    }

    int count() const { return static_cast<int>(m_all.size()); }

private:
    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }

    static bool matches(const std::string& item, const std::string& filter)
    {
        const std::string hay{ lower(item) };
        std::istringstream words{ lower(filter) };
        for (std::string w; words >> w;) if (hay.find(w) == std::string::npos) return false;
        return true;
    }

    static int compare(const Entity& a, const Entity& b, int column)
    {
        if (column == 0) return a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
        if (column == 1) return a.team < b.team ? -1 : a.team > b.team ? 1 : 0;
        if (column == 2) return a.hp < b.hp ? -1 : a.hp > b.hp ? 1 : 0;
        return 0;
    }

    std::vector<Entity> m_all;
    std::string m_filter;
    std::vector<SortSpec> m_specs;
    std::set<int> m_selected;
    int m_anchor{ -1 };
};

