using Ids = std::vector<int>;
EntityBrowser make() { return EntityBrowser({ { 1, "Bat", "red", 5 }, { 2, "Ant", "blue", 9 }, { 3, "Cat", "red", 9 }, { 4, "Dog", "blue", 2 }, { 5, "Eel", "red", 5 }, { 6, "Red Fox", "green", 7 } }); }
TEST("filter and sort") {
    auto b = make(); b.setFilter("red"); CHECK_EQ(b.rows(), (Ids{ 1, 3, 5, 6 }));
    b.setSort({ { 2, false }, { 0, true } }); CHECK_EQ(b.rows(), (Ids{ 3, 6, 1, 5 }));
    b.setFilter(""); CHECK_EQ(b.rows(), (Ids{ 2, 3, 6, 1, 5, 4 }));
}
TEST("selection survives filtering") {
    auto b = make(); b.click(4, false, false); b.click(1, true, false);
    b.setFilter("red"); CHECK_EQ(b.selected(), (Ids{ 1, 4 }));
}
TEST("shift uses the visible order") {
    auto b = make(); b.setSort({ { 0, true } });           // Ant Bat Cat Dog Eel "Red Fox": 2 1 3 4 5 6
    b.click(1, false, false); b.click(5, false, true); CHECK_EQ(b.selected(), (Ids{ 1, 3, 4, 5 }));
}
TEST("clipped rows") { auto b = make(); CHECK_EQ(b.visibleRows(20, 40, 20), (Ids{ 2, 3 })); CHECK_EQ(b.visibleRows(90, 100, 20), (Ids{ 5, 6 })); CHECK(b.visibleRows(0, 100, 0).empty()); }
TEST("delete the selection, including hidden ones") {
    auto b = make(); b.click(2, false, false); b.click(6, true, false);
    b.setFilter("blue"); b.removeSelected();
    CHECK_EQ(b.count(), 4); CHECK(b.selected().empty()); CHECK_EQ(b.rows(), (Ids{ 4 }));
    b.setFilter(""); CHECK_EQ(b.rows(), (Ids{ 1, 3, 4, 5 }));
}

